-- ONB-03: presentation text only; no client profile backfill.
CREATE TABLE onboarding_phrases (segment TEXT PRIMARY KEY, phrases JSONB NOT NULL CHECK(jsonb_typeof(phrases)='array' AND jsonb_array_length(phrases)>0), version_no INTEGER NOT NULL DEFAULT 1);
REVOKE ALL ON onboarding_phrases FROM PUBLIC;
GRANT SELECT, UPDATE ON onboarding_phrases TO radar_app;

ALTER TABLE onboarding_phrases ENABLE ROW LEVEL SECURITY;
ALTER TABLE onboarding_phrases FORCE ROW LEVEL SECURITY;
CREATE POLICY onboarding_phrases_read ON onboarding_phrases FOR SELECT TO radar_app USING (true);
CREATE POLICY onboarding_phrases_edit ON onboarding_phrases FOR UPDATE TO radar_app USING (EXISTS(SELECT 1 FROM platform_user_roles WHERE user_id=NULLIF(current_setting('app.user_id',true),'')::uuid AND role='PLATFORM_ADMIN' AND revoked_at IS NULL)) WITH CHECK (EXISTS(SELECT 1 FROM platform_user_roles WHERE user_id=NULLIF(current_setting('app.user_id',true),'')::uuid AND role='PLATFORM_ADMIN' AND revoked_at IS NULL));